package com.kuryelog.logic.orders

import com.kuryelog.logic.capture.*
import com.kuryelog.logic.core.*
import org.junit.Assert.*
import org.junit.Test

/** Transcribed visible facts from the courier's screenshots. Not an OCR-image accuracy claim. */
class CourierFlowTest {
    private val wolt = "com.wolt.partner"; private val bolt = "com.bolt.food.courier"
    private fun obs(pkg: String, at: Long, vararg text: String, actions: List<String> = emptyList(), complete: Boolean = true) = CourierParser.parse(pkg, text.toList(), actions, at, complete=complete)
    private fun boltOffer(at: Long=1000) = obs(bolt,at,"Decline","Cook Box by Merkez Lahmacun Nizami","Mehemmed Naxcivani 15","~8 min","~14 min","22 min, 4,49 ₼",actions=listOf("22 min, 4,49 ₼","Decline"))
    private fun woltOffer(at: Long=1000) = obs(wolt,at,"Ready in 3 min","Decline","₼2.31","2 stops (2.8 km) • 8–16 min","Izmir Doner Tantuni No1","9RQW+344 Baku, Baku, AZ1000","Customer drop-off","Mirzəağa Əliyev 249, Bakı, 1014","Accept",actions=listOf("Accept","Decline"))
    private fun pickup(pkg: String=bolt, at: Long=2000) = obs(pkg,at,"Order is being prepared","Arrive in 11 min","Xengeland","Mehdi Hüseyn 99","Orders to pick up:","2","#Q3FYM","Items (0)","#8P6D2")
    private fun idle(pkg: String=bolt,at: Long=3000) = obs(pkg,at,"Waiting for orders","Online")
    private fun drop(id: String="#8P6D2", at: Long=3000) = obs(bolt,at,"Drop off in -1 min","Ziba M. $id","Items (1)","Address","Mehdi Huseyn 40, Baku","Instructions","Meet at my door","Floor","3","Arrived","Slide to confirm",actions=listOf("Arrived"))
    @Test fun noShiftMeansNoDetection() { val c=DeliveryCore(); assertTrue(c.observe(boltOffer()).isEmpty()); assertTrue(c.pending.isEmpty()); assertTrue(c.trips.isEmpty()) }
    @Test fun bothVisiblePlatformsRemainIndependent() { val c=DeliveryCore(); c.start(); c.observe(woltOffer()); c.observe(boltOffer()); assertEquals(2,c.pending.size); c.observe(pickup()); assertTrue(c.pending.containsKey(wolt)); assertNotNull(c.active(bolt)); assertNull(c.active(wolt)) }
    @Test fun acceptedBoltNeverBecomesRejectedOnOfferDisappearance() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); val events=c.observe(pickup()); assertEquals("accepted",events.first().type); assertFalse(events.any { it.type=="rejected" }); assertEquals(4.49,c.active(bolt)!!.gross!!,0.001) }
    @Test fun lateOcrOfferCannotResurrectAcceptedJob() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); c.observe(pickup()); c.observe(boltOffer(1500).copy(source="ocr")); c.observe(pickup(at=3000)); assertTrue(c.pending.isEmpty()); assertEquals(1,c.trips.size) }
    @Test fun observedIdleAfterOfferMeansRejected() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); assertTrue(c.observe(idle()).isEmpty()); assertEquals("rejected",c.observe(idle(at=3500)).single().type) }
    @Test fun appSwitchNeverRejectsOtherPlatform() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); c.observe(idle(wolt)); c.observe(idle(wolt,4000)); assertTrue(c.pending.containsKey(bolt)) }
    @Test fun closedUnreadablePanelDoesNotReject() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); c.observe(obs(bolt,5000,"Baku","Mapbox","Show map")); assertTrue(c.pending.containsKey(bolt)) }
    @Test fun incompleteIdleFrameDoesNotReject() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); c.observe(idle().copy(complete=false)); c.observe(idle(at=7000).copy(complete=false)); assertTrue(c.pending.containsKey(bolt)) }
    @Test fun aLoadingFrameDoesNotCompleteDelivery() { val c=DeliveryCore(); c.start(); c.observe(drop()); c.observe(obs(bolt,4000,"Drop off in -7 min","Ramil S. #CCUV5","Address","Təbriz 52, Баку","Floor","3","✓")); assertNull(c.active(bolt)!!.completedAt) }
    @Test fun boltBundleUsesOrderIdsNotItems() { val o=pickup(); assertEquals(2,o.quantity); assertEquals(listOf("#Q3FYM","#8P6D2"),o.orderIds); val c=DeliveryCore(); c.start(); c.observe(o); assertEquals(2,c.active(bolt)!!.expectedOrders) }
    @Test fun restaurantReadyDoesNotMeanPickedUp() { val o=obs(bolt,2000,"Order is ready for pickup","Arrived","Pizza Hut Zoo"); val c=DeliveryCore(); c.start(); c.observe(o); assertEquals(TripPhase.WAITING,c.active(bolt)!!.phase); assertNull(c.active(bolt)!!.pickups.single().pickedAt) }
    @Test fun woltPickupAfterOfferRetainsPrice() { val c=DeliveryCore(); c.start(); c.observe(woltOffer()); c.observe(obs(wolt,2000,"Pickup 3 min","Pickup from","Donerist-Kebabist Sahil","Sabail district, Uzeyir Hajibeyov str., 27, AZ1000 Baku",actions=listOf("Collect"))); assertEquals(2.31,c.active(wolt)!!.gross!!,0.001); assertEquals(TripPhase.TO_RESTAURANT,c.active(wolt)!!.phase) }
    @Test fun pickupToCustomerMarksCollection() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(drop()); assertEquals(3000L,c.active(bolt)!!.pickups.single().pickedAt); assertEquals(TripPhase.TO_CUSTOMER,c.active(bolt)!!.phase) }
    @Test fun confirmedNextCustomerIsIndependent() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(drop()); c.click(bolt,"Complete delivery",3200); c.observe(drop("#Q3FYM",4000)); val t=c.active(bolt)!!; assertEquals(4000L,t.customers["#8P6D2"]!!.deliveredAt); assertNull(t.customers["#Q3FYM"]!!.deliveredAt); assertNull(t.completedAt) }
    @Test fun notesDontLeakBetweenCustomers() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(drop()); c.observe(obs(bolt,4000,"Drop off in 2 min","Arif #Q3FYM","Address","Elsewhere 10","Additional note","Use back door")); val t=c.active(bolt)!!; assertNull(t.customers["#Q3FYM"]!!.details.floor); assertEquals("3",t.customers["#8P6D2"]!!.details.floor) }
    @Test fun restaurantWaitAndLatenessAreDifferent() { val c=DeliveryCore(); c.start(); c.observe(pickup(at=0)); c.observe(obs(bolt,600000,"Order is ready for pickup","Arrived","Xengeland","Mehdi Hüseyn 99")); c.observe(drop(at=780000)); val t=c.active(bolt)!!; assertEquals(3.0,t.waitMinutes,0.001)
        // 0.11: Bolt's "Arrive in 11 min" is the courier's arrival target, not the ready time (courier, 6 Oct 2026).
        assertNull(t.pickups.single().readyAt); assertEquals(600000L,t.pickups.single().readyObservedAt); assertEquals(3.0,t.lateMinutes,0.001) }
    @Test fun completionNeedsEvidence() { val c=DeliveryCore(); c.start(); c.observe(drop()); c.observe(idle(at=6000)); c.observe(idle(at=7000)); assertNull(c.active(bolt)!!.completedAt) }
    @Test fun confirmedDeliveryToIdleCompletes() { val c=DeliveryCore(); c.start(); c.observe(drop()); c.click(bolt,"Complete delivery",3500); c.observe(idle(at=4000)); assertEquals("delivered",c.observe(idle(at=4500)).single().type); assertEquals(TripPhase.FINISHED,c.trips.values.single().phase) }
    @Test fun explicitCompletedMessageDoesNotMakeRepeatedJobs() { val c=DeliveryCore(); c.start(); c.observe(drop()); val done=obs(bolt,4000,"Delivery completed"); c.observe(done); c.observe(done.copy(at=4500)); c.observe(drop(at=5000)); assertEquals(1,c.trips.size); assertEquals(TripPhase.FINISHED,c.trips.values.single().phase) }
    @Test fun genericConfirmIsContextualAndNeedsNextScreen() { val c=DeliveryCore(); c.start(); c.observe(pickup().copy(quantity=1,orderIds=listOf("#8P6D2"))); c.click(bolt,"Confirm",2100); assertNull(c.active(bolt)!!.finishIntentAt); c.observe(drop()); c.click(bolt,"Confirm",3200); assertNull(c.active(bolt)!!.completedAt); c.observe(idle(at=4000)); c.observe(idle(at=4500)); assertEquals(TripPhase.FINISHED,c.trips.values.single().phase) }
    @Test fun firstBundleCompletionDoesNotFinishOtherCustomer() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(drop()); c.observe(obs(bolt,4000,"Delivery completed")); val t=c.active(bolt)!!; assertEquals(4000L,t.customers["#8P6D2"]!!.deliveredAt); assertNull(t.customers["#Q3FYM"]!!.deliveredAt); assertNull(t.completedAt); c.observe(obs(bolt,4500,"Delivery completed")); assertNotNull(c.active(bolt)); c.observe(drop("#Q3FYM",5000)); c.observe(obs(bolt,6000,"Delivery completed")); assertEquals(6000L,t.completedAt); assertEquals(2,t.customers.values.count { it.deliveredAt!=null }); assertEquals(1,c.trips.size) }
    @Test fun bundleConfirmToIdleOnlyCompletesCurrentCustomer() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(drop()); c.click(bolt,"Complete delivery",3200); c.observe(idle(at=4000)); c.observe(idle(at=4500)); val t=c.active(bolt)!!; assertNotNull(t.customers["#8P6D2"]!!.deliveredAt); assertNull(t.customers["#Q3FYM"]!!.deliveredAt); c.observe(drop("#Q3FYM",5000)); c.click(bolt,"Complete delivery",5500); c.observe(idle(at=6000)); c.observe(idle(at=6500)); assertEquals(TripPhase.FINISHED,t.phase) }
    @Test fun noAutomaticCompletionFromElapsedTime() { val c=DeliveryCore(); c.start(); c.observe(drop()); c.observe(obs(bolt,86400000,"Baku")); assertNull(c.active(bolt)!!.completedAt) }
    @Test fun stopDisablesEngineAndLeavesUnknownOutcome() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.stop(5000); c.observe(boltOffer(6000)); assertTrue(c.pending.isEmpty()); assertEquals(TripPhase.END_UNCONFIRMED,c.trips.values.single().phase) }
    @Test fun bundleDistanceIsNotDuplicated() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.addDistance(1000.0); val t=c.active(bolt)!!; assertEquals(1000.0,t.distanceM,0.001); assertEquals(2,t.customers.size) }
    @Test fun concurrentPlatformDistanceIsAllocatedOnce() { val c=DeliveryCore(); c.start(); c.observe(pickup()); c.observe(pickup(wolt,2100)); c.addDistance(1200.0); assertEquals(1200.0,c.trips.values.sumOf { it.distanceM },0.001) }
    @Test fun netFeeAndTipDontLoseCommissionMeaning() { val c=DeliveryCore(); c.start(); c.observe(boltOffer()); c.observe(pickup()); val t=c.active(bolt)!!; t.commissionPct=10.0; t.tip=1.0; assertEquals(5.041,t.net!!,0.001); t.priceIsNet=true; assertEquals(5.041,t.net!!,0.001) }
}
